startGuideActionCreate: "作成",
startGuideActionMenu: "メニューを選択",
startGuideActivity: "アクティビティとはあなたのプロジェクトで計画されたタスクです。<br/>あなたはプロジェクト内にWBSを階層無制限に作成できます。",
startGuideAffectation: "リソースはプロジェクトの項目を扱える関係者です。<br/>プロジェクトの関係者はサブプロジェクトの項目も扱うことができます。",
startGuideClient: "顧客とはあなたが奉仕する対象です。<br/>顧客はあなたの組織外だけでなく組織内にも存在します。",
startGuideContact: "顧客担当者とは顧客の中であなたたちが接触する人です。",
startGuideFooter: "これらがメイン機能です。<br/>これらメイン機能から、プロジェクト管理に必要な細部機能にアクセスすることができます。",
startGuideImputation: "リソースは日ごとアクティビティごとに実績作業入力画面で実績作業を入力します。<br/>残作業の再見積もりを行うことで、プロジェクト計画をより確かなものにすることができます。",
startGuideIntro: "このスタートガイドはあなたがProjeQtOrをはじめて利用するのを手助けする簡易ヘルプです。<br/>これらの手順に従って最初の操作を実施してください。<br/>手助けが必要なときはいつでもF1キーを押してください。<br/>「今日」のページからこのスタートガイドページを開くことができます。",
startGuideMilestone: "マイルストーンとはプロジェクトの節目となる日です。<br/>固定的あるいは流動的なマイルストーンを設定できます。",
startGuidePlanning: "計画はガントチャートビューで行います。<br/>アクティビティを作成したら、担当するリソースを設定し作業を定義します。<br/>その後に作業とマイルストーンの関係を定義します。<br/>そして利用可能なリソースを念頭において計画立案します。",
startGuideProject: "プロジェクトはProjeQtOrのメイン項目です。<br/>すべての項目はプロジェクトと関連付きます。<br/>アクセス制御はプロジェクトごとになされます。",
startGuideResource: "リソースは作業を実施する人です。<br/>「ユーザー」としてチェックされている場合にProjeQtOrにログインすることができます。",
startGuideTicket: "チケットはバグや要求などの出来事をプロジェクトに関連付けるためのものです。<br/>チケットは、再入力することなく、簡易にアクティビティと関連付けることができます。",
startGuideTitle: "スタートガイド",
startGuideUser: "ユーザーはProjeQtOrにログインできる人です。<br/>ユーザーには要素に対するアクセス権を付与する必要があります。",
